"""Contract tests for embedded XMID generated by Song Studio Pro."""
import hashlib
import struct
import tempfile
import unittest
from pathlib import Path

from karaoke.xmid_reader import read_xmid, decode_metadata, HEADER, MAGIC


def field(value):
    data = value.encode("utf-8")
    return struct.pack("<I", len(data)) + data


def fixture():
    meta = b"".join(field(v) for v in
                    ("song-1", "00074648", "rev-1", "เพลงทดสอบ", "ศิลปิน", "verified"))
    meta += struct.pack("<I", 1)
    meta += struct.pack("<dd", 1.0, 2.0) + field("สวัสดี") + field("verified")
    meta += struct.pack("<I", 2)
    meta += struct.pack("<dd", 1.0, 0.4) + field("สวัส")
    meta += struct.pack("<dd", 1.4, 0.6) + field("ดี")
    midi = (b"MThd" + struct.pack(">IHHH", 6, 0, 1, 480)
            + b"MTrk" + struct.pack(">I", 4) + b"\x00\xff\x2f\x00")
    header = HEADER.pack(MAGIC, 1, len(meta), len(midi),
                         hashlib.sha256(midi).digest(), hashlib.sha256(meta).digest())
    return header + meta + midi


class XmidReaderTests(unittest.TestCase):
    def test_embedded_midi_and_exact_cues(self):
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / "sample.xmid"
            path.write_bytes(fixture())
            midi, doc = read_xmid(path)
            self.assertEqual(midi[:4], b"MThd")
            self.assertEqual(doc["title"], "เพลงทดสอบ")
            self.assertEqual([(c["startTime"], c["text"]) for c in doc["lines"][0]["cues"]],
                             [(1.0, "สวัส"), (1.4, "ดี")])

    def test_reject_modified_media_and_metadata(self):
        blob = fixture()
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / "sample.xmid"
            for offset in (HEADER.size + 10, len(blob) - 1):
                corrupt = bytearray(blob)
                corrupt[offset] ^= 1
                path.write_bytes(corrupt)
                with self.assertRaises(ValueError):
                    read_xmid(path)

    def test_reject_truncated_container(self):
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / "sample.xmid"
            path.write_bytes(fixture()[:-1])
            with self.assertRaises(ValueError):
                read_xmid(path)


if __name__ == "__main__":
    unittest.main()
